// Source-derived tier math; optional gated live blending is in tier_live.
// REA: ev_10a1736d... midrank; ev_8317f3d3... Bayesian winrate;
// ev_afeafef6... presence; tier-weighted-score.asm damage=max(atk,AP).
#[derive(Clone,Debug)]pub struct Champion{pub name:String,pub category:usize,pub base:[f32;6],pub growth:[f32;6],pub speed:f32,pub range:f32}
pub fn percentile(values:&[f32])->Vec<f32>{if values.len()<2{return vec![0.5;values.len()]};values.iter().map(|x|{let below=values.iter().filter(|v|**v<*x).count() as f32;let equal=values.iter().filter(|v|**v==*x).count()as f32;(below+equal*0.5)/values.len()as f32}).collect()}
pub fn win_rate(wins:u64,matches:u64,k:f32)->f32{let total=matches as f32+k;if total>0.0{(wins as f32+k*0.5)/total}else{0.5}}
pub fn stat_scores(champions:&[Champion],level:f32,weights:[f32;7])->Vec<f32>{
 let step=(level.clamp(1.0,12.0)-1.0)/11.0;
 let features:Vec<[f32;8]>=champions.iter().map(|c|{let mut r=[0.0;8];for i in 0..6{r[i]=(c.base[i]+c.growth[i]*11.0)*step+(1.0-step)*c.base[i];}r[6]=c.speed;r[7]=c.range;r}).collect();
 let normalized:Vec<Vec<f32>>=(0..8).map(|i|percentile(&features.iter().map(|r|r[i]).collect::<Vec<_>>())).collect();
 let sum: f32=weights.iter().sum();(0..champions.len()).map(|i|{if sum<=0.0{return 0.0;}let damage=normalized[0][i].max(normalized[1][i]);let mut score=damage*weights[0];for k in 1..7{score+=normalized[k+1][i]*weights[k];}score/sum}).collect()
}
pub fn assign(champions:&[Champion],scores:&[f32],overall:bool)->Vec<(String,char)>{assert_eq!(champions.len(),scores.len());let cuts=[0.15,0.35,0.65,0.85];let tier=|top:f32|{if top<cuts[0]{'S'}else if top<cuts[1]{'A'}else if top<cuts[2]{'B'}else if top<cuts[3]{'C'}else{'D'}};let mut result=Vec::new();if overall{for(c,p)in champions.iter().zip(percentile(scores)){result.push((c.name.clone(),tier(1.0-p)));}}else{for category in 0..5{let mut indices:Vec<_>=champions.iter().enumerate().filter(|(_,c)|c.category==category).map(|(i,_)|i).collect();indices.sort_by(|a,b|scores[*b].total_cmp(&scores[*a]));for(rank,i)in indices.iter().enumerate(){result.push((champions[*i].name.clone(),tier((rank as f32+0.5)/indices.len()as f32)));}}}result}
#[cfg(test)]mod tests{use super::*;#[test]fn observed_midrank_and_bayes(){assert_eq!(percentile(&[1.,1.,3.,4.]),vec![0.25,0.25,0.625,0.875]);assert_eq!(win_rate(0,0,20.),0.5);assert!((win_rate(10,10,20.)-2./3.).abs()<1e-6);}#[test]fn damage_is_max_of_attack_and_ap_percentiles(){let c=|name:&str,a:f32,m:f32|Champion{name:name.into(),category:0,base:[a,m,0.,0.,0.,0.],growth:[0.;6],speed:0.,range:0.};let scores=stat_scores(&[c("a",100.,0.),c("b",0.,100.),c("c",50.,50.)],6.5,[1.,0.,0.,0.,0.,0.,0.]);assert_eq!(scores[0],scores[1]);assert!(scores[0]>scores[2]);}#[test]fn per_role_singleton_and_overall_ties_are_b(){let c=|name:&str,category|Champion{name:name.into(),category,base:[0.;6],growth:[0.;6],speed:0.,range:0.};let cs=[c("a",0),c("b",1)];assert!(assign(&cs,&[0.5,0.5],false).iter().all(|(_,t)|*t=='B'));assert!(assign(&cs,&[0.5,0.5],true).iter().all(|(_,t)|*t=='B'));}}
